script:
frappe.ui.form.on('Revive Job Card Spares Used', {
    item: function(frm, cdt, cdn) {
        calculate_total(cdt, cdn);
    },

    qty: function(frm, cdt, cdn) {
        calculate_total(cdt, cdn);
    },

    rate: function(frm, cdt, cdn) {
        calculate_total(cdt, cdn);
    }
});

function calculate_spare_total(cdt, cdn) {
    let row = locals[cdt][cdn];

    let total = (row.qty || 0) * (row.rate || 0);

    frappe.model.set_value(cdt, cdn, 'total', total);
}

frappe.ui.form.on('Revive Job Card Repairs Done', {
    repair: function(frm, cdt, cdn) {
        calculate_total(cdt, cdn);
    },

    qty: function(frm, cdt, cdn) {
        calculate_total(cdt, cdn);
    },

    rate: function(frm, cdt, cdn) {
        calculate_total(cdt, cdn);
    }
});

function calculate_labour_row_total(cdt, cdn) {
    let row = locals[cdt][cdn];

    let total = (row.qty || 0) * (row.rate || 0);

    frappe.model.set_value(cdt, cdn, 'total', total);
}

frappe.ui.form.on('Revive Job Card', {
    refresh(frm) {
        calculate_spares_total(frm);
        creat_sales_invoice(frm);
        // make_payment_entry(frm);
    },

    spare_total(frm) {
        calculate_grand_total(frm);
    },

    labour_total(frm) {
        calculate_grand_total(frm);
    },
     grand_total(frm) {
        calculate_discount(frm);
    },

    discount_amount(frm) {
        if (!frm._calculating_discount) {
            calculate_discount(frm, 'amount');
        }
    },

    discount_percentage(frm) {
        if (!frm._calculating_discount) {
            calculate_discount(frm, 'percentage');
        }
    }

});

frappe.ui.form.on('Revive Job Card Spares Used', {
    total(frm, cdt, cdn) {
        calculate_spares_total(frm);
    },
    spares_used_remove(frm, cdt, cdn) {
        calculate_spares_total(frm);
    },
    // item: function(frm, cdt, cdn) {
    //     calculate_spare_total(cdt, cdn);
    // },
    item: function(frm, cdt, cdn) {
        calculate_spare_total(cdt, cdn);
        let row = locals[cdt][cdn];

        if (!row.item) {
            return;
        }

        frappe.db.get_value(
            "Item Price",
            {
                item_code: row.item,
                price_list: "Standard Selling"
            },
            "price_list_rate"
        ).then(r => {

            if (r.message && r.message.price_list_rate) {
                frappe.model.set_value(
                    cdt,
                    cdn,
                    "rate",
                    r.message.price_list_rate
                );
            } else {
                frappe.model.set_value(cdt, cdn, "rate", 0);

                frappe.msgprint(
                    __("No selling price found for {0} in Standard Selling.", [row.item])
                );
            }

        });
    },

    qty: function(frm, cdt, cdn) {
        calculate_spare_total(cdt, cdn);
    },

    rate: function(frm, cdt, cdn) {
        calculate_spare_total(cdt, cdn);
    }
});


function calculate_spare_total(cdt, cdn) {
    let row = locals[cdt][cdn];

    let total = (row.qty || 0) * (row.rate || 0);

    frappe.model.set_value(cdt, cdn, 'total', total);
}

frappe.ui.form.on('Revive Job Card Repairs Done', {
    total(frm, cdt, cdn) {
        calculate_labour_total(frm);
    },
    labour_work_done_remove(frm, cdt, cdn) {
        calculate_labour_total(frm);
    },
    repair: function(frm, cdt, cdn) {
        calculate_labour_row_total(cdt, cdn);
        let row = locals[cdt][cdn];

        if (!row.repair) {
            return;
        }

        frappe.db.get_value(
            "Item Price",
            {
                item_code: row.repair,
                price_list: "Standard Selling"
            },
            "price_list_rate"
        ).then(r => {

            if (r.message && r.message.price_list_rate) {
                frappe.model.set_value(
                    cdt,
                    cdn,
                    "rate",
                    r.message.price_list_rate
                );
            } else {
                frappe.model.set_value(cdt, cdn, "rate", 0);

                frappe.msgprint(
                    __("No selling price found for {0} in Standard Selling.", [row.item])
                );
            }

        });
    },

    qty: function(frm, cdt, cdn) {
        calculate_labour_row_total(cdt, cdn);
    },

    rate: function(frm, cdt, cdn) {
        calculate_labour_row_total(cdt, cdn);
    }
});

function calculate_labour_row_total(cdt, cdn) {
    let row = locals[cdt][cdn];

    let total = (row.qty || 0) * (row.rate || 0);

    frappe.model.set_value(cdt, cdn, 'total', total);
}

function calculate_labour_total(frm) {
    let total = 0;

    (frm.doc.labour_work_done || []).forEach(row => {
        total += flt(row.total);
    });

    frm.set_value('labour_total', total);
}

function calculate_spares_total(frm) {
    let total = 0;

    (frm.doc.spares_used || []).forEach(row => {
        total += flt(row.total);
    });

    frm.set_value('spare_total', total);
}

function calculate_grand_total(frm) {
    let spare_total = flt(frm.doc.spare_total);
    let labour_total = flt(frm.doc.labour_total);

    frm.set_value('grand_total', spare_total + labour_total);
}

function calculate_discount(frm, source) {
    let grand_total = flt(frm.doc.grand_total);

    if (!grand_total) {
        frm.set_value('discounted_amount', 0);
        frm.set_value('amount_after_discount', 0);
        return;
    }

    frm._calculating_discount = true;

    let discount_amount = 0;
    let discount_percentage = 0;

    if (source === 'percentage') {
        // Percentage was entered → calculate amount
        discount_percentage = flt(frm.doc.discount_percentage);

        discount_amount = grand_total * discount_percentage / 100;

    } else {
        // Amount was entered → calculate percentage
        discount_amount = flt(frm.doc.discount_amount);

        discount_percentage = (discount_amount / grand_total) * 100;
    }

    // Prevent discount from exceeding grand total
    discount_amount = Math.min(discount_amount, grand_total);

    // Recalculate percentage after limiting discount amount
    discount_percentage = (discount_amount / grand_total) * 100;

    frm.set_value('discount_amount', discount_amount);
    frm.set_value('discount_percentage', discount_percentage);
    frm.set_value('discounted_amount', discount_amount);
    frm.set_value(
        'amount_after_discount',
        grand_total - discount_amount
    );

    frm._calculating_discount = false;
}

function creat_sales_invoice(frm){
            if (frm.is_new()) {
            return;
        }

        frm.add_custom_button('Create Invoice', () => {

            frappe.confirm(
                'Create and submit Sales Invoice(s) for this Job Card?',
                () => {

                    frappe.call({
                        method: 'rarison_motors.api.revive_job_card.create_job_card_invoices',
                        args: {
                            job_card_name: frm.doc.name
                        },
                        freeze: true,
                        freeze_message: 'Creating and submitting invoice(s)...',

                        callback: function(r) {

                            if (!r.message) {
                                return;
                            }

                            const result = r.message;

                            if (!result.success) {
                                frappe.msgprint({
                                    title: 'No Invoices Created',
                                    message: result.message,
                                    indicator: 'orange'
                                });
                                return;
                            }

                            // Refresh the document so the invoice fields
                            // show the newly created invoice numbers.
                            frm.reload_doc().then(() => {

                                let invoices = [];

                                if (result.spares_invoice) {
                                    invoices.push(
                                        `<b>Spares Invoice:</b> ${result.spares_invoice}`
                                    );
                                }

                                if (result.service_invoice) {
                                    invoices.push(
                                        `<b>Service Invoice:</b> ${result.service_invoice}`
                                    );
                                }

                                frappe.msgprint({
                                    title: 'Invoice(s) Created',
                                    message:
                                        'The invoice(s) were created and submitted successfully.<br><br>' +
                                        invoices.join('<br>'),
                                    indicator: 'green'
                                });
                            });
                        },

                        error: function() {
                            frappe.msgprint({
                                title: 'Invoice Creation Failed',
                                message: 'An error occurred while creating the invoice(s). No changes were made to the Job Card.',
                                indicator: 'red'
                            });
                        }
                    });

                },
                () => {
                    // User clicked No
                }
            );

        });
}

frappe.ui.form.on('Payment Entry', {
    on_submit(frm) {
        if (!frm.doc.custom_job_card) {
            return;
        }

        frappe.show_alert({
            message: __('Payment Entry submitted successfully'),
            indicator: 'green'
        });

        setTimeout(() => {
            frappe.set_route(
                'Form',
                'Revive Job Card',
                frm.doc.custom_job_card
            );
        }, 500);
    }
});
